tool_calls.name:
/bin/zsh -lc "cat > /tmp/config.go.new <<'EOF'
package config

import \"fmt\"

type Config struct {
	Host       string
	ListenPort int
}

func DefaultConfig() *Config {
	return &Config{
		Host:       \"localhost\",
		ListenPort: 8080,
	}
}

func (c *Config) Addr() string {
	return fmt.Sprintf(\"%s:%d\", c.Host, c.ListenPort)
}
EOF
python3 -c 'import os; p=\"config/config.go\"; q=\"/tmp/config.go.new\"; d=open(q,\"rb\").read(); t=p+\".tmp\"; f=open(t,\"wb\"); f.write(d); f.flush(); os.fsync(f.fileno()); f.close(); os.replace(t,p)' && git diff -- config/config.go"

